    pub tws_host: String,
    pub tws_port: u16,
    pub client_id: i32,
    pub paper_trading: bool,
    pub log_level: String,
}

impl Config {
    pub fn from_env() -> Result<Self> {
        dotenv().ok();

        let tws_host = env::var("TWS_HOST").unwrap_or_else(|_| "127.0.0.1".to_string());
        let tws_port = env::var("TWS_PORT")
            .unwrap_or_else(|_| "7500".to_string())
            .parse::<u16>()
