use crate::config::Config;
use crate::error::{Error, Result};
use ibapi::prelude::*;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::RwLock;
use tokio::time::{sleep, timeout};
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone)]
pub enum ConnectionStatus {
    Disconnected,
    Connecting,
    Connected,
    Error(String),
}

pub struct ConnectionManager {
    client: Arc<RwLock<Option<Client>>>,
    config: Config,
    status: Arc<RwLock<ConnectionStatus>>,
    retry_attempts: u32,
    max_retries: u32,
}

impl ConnectionManager {
    pub fn new(config: Config) -> Self {
        Self {
            client: Arc::new(RwLock::new(None)),
            config,
            status: Arc::new(RwLock::new(ConnectionStatus::Disconnected)),
            retry_attempts: 0,
            max_retries: 5,
        }
    }

    pub async fn connect(&mut self) -> Result<()> {
        self.set_status(ConnectionStatus::Connecting).await;

        let connection_url = self.config.connection_url();
        info!("Attempting to connect to TWS at {}", connection_url);

        match self.connect_with_retry().await {
            Ok(client) => {
                info!("Successfully connected to TWS");
                *self.client.write().await = Some(client);
                self.set_status(ConnectionStatus::Connected).await;
                self.retry_attempts = 0;
                Ok(())
            }
            Err(e) => {
                error!("Failed to connect to TWS: {}", e);
                self.set_status(ConnectionStatus::Error(e.to_string())).await;
                Err(e)
            }
        }
    }

    async fn connect_with_retry(&mut self) -> Result<Client> {
        let mut backoff = Duration::from_secs(1);

        while self.retry_attempts < self.max_retries {
            match Client::connect(&self.config.connection_url(), self.config.client_id) {
                Ok(client) => return Ok(client),
                Err(e) => {
                    self.retry_attempts += 1;
                    warn!(
                        "Connection attempt {} failed: {}. Retrying in {:?}...",
                        self.retry_attempts, e, backoff
                    );

                    if self.retry_attempts >= self.max_retries {
                        return Err(Error::Connection(format!(
                            "Failed to connect after {} attempts: {}",
                            self.max_retries, e
                        )));
                    }

                    sleep(backoff).await;
                    backoff = backoff.saturating_mul(2).min(Duration::from_secs(30));
                }
            }
        }

        Err(Error::Connection(format!(
            "Maximum retry attempts ({}) exceeded",
            self.max_retries
        )))
    }

    pub async fn disconnect(&mut self) -> Result<()> {
        if let Some(mut client) = self.client.write().await.take() {
            info!("Disconnecting from TWS");
            client.disconnect();
            self.set_status(ConnectionStatus::Disconnected).await;
        }
        Ok(())
    }

    pub async fn is_connected(&self) -> bool {
        matches!(
            *self.status.read().await,
            ConnectionStatus::Connected
        )
    }

    pub async fn get_client(&self) -> Option<Client> {
        self.client.read().await.clone()
    }

    pub async fn get_status(&self) -> ConnectionStatus {
        self.status.read().await.clone()
    }

    async fn set_status(&self, status: ConnectionStatus) {
        *self.status.write().await = status;
    }

    pub async fn health_check(&self) -> Result<()> {
        if !self.is_connected().await {
            return Err(Error::Connection("Not connected to TWS".to_string()));
        }

        debug!("Performing health check");
        Ok(())
    }
}
